mapper.select:
SELECT COUNT(*) FROM knowledge_ingestion WHERE tenant_id=#{tenant}

    AND status='PROCESSING' AND lease_until>UTC_TIMESTAMP(6)
    AND status IN ('RECEIVED','PROCESSING')

SELECT slot_number FROM knowledge_capacity_slot WHERE tenant_id=#{tenant} AND lane=#{lane}
  AND (lease_token IS NULL OR lease_until<=UTC_TIMESTAMP(6))
ORDER BY slot_number LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE knowledge_capacity_slot SET lease_token=#{token},lease_until=TIMESTAMPADD(SECOND,#{seconds},UTC_TIMESTAMP(6))
WHERE tenant_id=#{tenant} AND lane=#{lane} AND slot_number=#{slot}
  AND (lease_token IS NULL OR lease_until<=UTC_TIMESTAMP(6))

UPDATE knowledge_capacity_slot SET lease_token=NULL,lease_until=NULL
WHERE tenant_id=#{tenant} AND lane=#{lane} AND slot_number=#{slot}
  AND lease_token=#{token} AND lease_until>UTC_TIMESTAMP(6)
